package local.skyfamily;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.os.Build;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class PaperActivity extends FrameActivity {
 static final int PAPER=0xfff2eee6,PAPER2=0xffe8e2d5,CARD=0xfffbf9f4,INK=0xff111111,MUTE=0xff7a756b,LINE=0xffd6cfc0;static final String WEATHER_TV="https://weatherstar.netbymatt.com/";boolean tvActive=false;FrameLayout tvStage;TextView tvStatus;
 @Override ThemeArt.Palette palette(){String theme=ThemeArt.active(prefs);int signal=theme.equals("christmas")?0xffa6312d:theme.equals("halloween")||theme.equals("fall")?0xffa25b24:theme.equals("spring")||theme.equals("stpatrick")?0xff276340:theme.equals("winter")?0xff27567c:theme.equals("birthday")?0xff85416c:INK;ThemeArt.Palette p=new ThemeArt.Palette(theme,PAPER,PAPER2,CARD,signal);p.muted=MUTE;return p;}
 @Override android.graphics.drawable.Drawable controlBackground(){StateListDrawable s=new StateListDrawable();s.addState(new int[]{android.R.attr.state_pressed},shape(PAPER2,INK,16));s.addState(new int[]{android.R.attr.state_selected},shape(CARD,palette().accent,16));s.addState(new int[]{},shape(CARD,LINE,16));return s;}
 @Override TextView label(String value,int size,int color){TextView t=super.label(value,size,color==fg?INK:color==muted?MUTE:color==accent?palette().accent:color);t.setTypeface(Typeface.create(size>=20?"sans-serif-condensed":"sans-serif",size>=20?Typeface.BOLD:Typeface.NORMAL));return t;}
 @Override EditText input(String hint,String value){EditText e=super.input(hint,value);e.setTextColor(INK);e.setHintTextColor(MUTE);e.setBackground(shape(CARD,LINE,12));return e;}
 @Override String group(String title){if(title.equals("Today"))return "Home";return super.group(title);}
 @Override void page(String title){stopTv();super.page(title);}
 @Override void normalize(View v){super.normalize(v);if(v instanceof ControlIcon&&v.getLayerType()!=View.LAYER_TYPE_SOFTWARE){Paint p=new Paint();p.setColorFilter(new PorterDuffColorFilter(INK,PorterDuff.Mode.SRC_IN));v.setLayerType(View.LAYER_TYPE_SOFTWARE,p);}if(v instanceof CheckBox)((CheckBox)v).setTextColor(INK);if(v instanceof TextView&&v.getParent()==body){TextView t=(TextView)v;int c=t.getCurrentTextColor();if(c==fg)t.setTextColor(INK);else if(c==muted)t.setTextColor(MUTE);else if(c==accent)t.setTextColor(palette().accent);}}
 TextView paperText(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(5));return t;}
 LinearLayout paperPanel(String title){LinearLayout p=new LinearLayout(this);p.setOrientation(1);p.setPadding(dp(18),dp(16),dp(18),dp(14));p.setBackground(shape(CARD,LINE,18));TextView heading=paperText(title.toUpperCase(Locale.US),16,MUTE);heading.setTypeface(Typeface.DEFAULT_BOLD);p.addView(heading);return p;}
 void addPanel(LinearLayout row,View child,float weight,boolean horizontal){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(horizontal?0:-1,-2,horizontal?weight:0);lp.setMargins(dp(5),dp(5),dp(5),dp(5));row.addView(child,lp);}
 @Override void home(){page("Today");header.setVisibility(View.GONE);boolean wide=getResources().getConfiguration().screenWidthDp>=760;LinearLayout top=new LinearLayout(this);top.setOrientation(wide?0:1);body.addView(top);LinearLayout clock=new LinearLayout(this);clock.setOrientation(1);clock.setPadding(dp(8),dp(12),dp(8),dp(12));TextClock time=new TextClock(this);time.setFormat12Hour("h:mm a");time.setFormat24Hour("HH:mm");time.setTextSize(wide?64:52);time.setTextColor(INK);time.setTypeface(Typeface.create("sans-serif-condensed",Typeface.BOLD));clock.addView(time);TextView date=paperText(new java.text.SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),22,INK);date.setTypeface(Typeface.SERIF);clock.addView(date);View rule=new View(this);rule.setBackgroundColor(INK);clock.addView(rule,new LinearLayout.LayoutParams(-1,dp(3)));addPanel(top,clock,1,wide);addPanel(top,weatherSummary(),1.15f,wide);LinearLayout main=new LinearLayout(this);main.setOrientation(wide?0:1);body.addView(main);LinearLayout left=new LinearLayout(this);left.setOrientation(1);left.addView(todayPanel(),new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams agendaSize=new LinearLayout.LayoutParams(-1,-2);agendaSize.topMargin=dp(12);left.addView(agendaPanel(),agendaSize);addPanel(main,left,1.2f,wide);addPanel(main,photoPanel(),1,wide);HorizontalScrollView quick=new HorizontalScrollView(this);quick.setHorizontalScrollBarEnabled(false);LinearLayout shortcuts=new LinearLayout(this);quick.addView(shortcuts);body.addView(quick,new LinearLayout.LayoutParams(-1,dp(76)));shortcut(shortcuts,"School",()->schoolHome());shortcut(shortcuts,"Books",()->bookshelf());shortcut(shortcuts,"Create",()->frameCreate());shortcut(shortcuts,"Games",()->puzzle());shortcut(shortcuts,"Uploads",()->uploadHub());shortcut(shortcuts,"Weather TV",()->weatherTvIntro());shortcut(shortcuts,"Explore",()->frameExplore());ArrayList<String> names=ThemeArt.today(prefs);if(!names.isEmpty())text("Happy birthday, "+android.text.TextUtils.join(", ",names)+"!");String scene=ThemeArt.scene(prefs);if(!scene.equals("off"))body.addView(new ThemeArt.Scene(this,scene,prefs.getBoolean("visual.motion",false)),new LinearLayout.LayoutParams(-1,dp(100)));shownDay=ThemeArt.dateKey(Calendar.getInstance());atHome=true;armIdle();}
 void shortcut(LinearLayout row,String title,Runnable run){iconControl(row,title,run);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(102),dp(64));lp.setMargins(dp(4),dp(6),dp(4),0);row.getChildAt(row.getChildCount()-1).setLayoutParams(lp);}
 LinearLayout weatherSummary(){LinearLayout p=paperPanel("Local forecast");try{JSONObject location=new JSONObject(get("planetary.location")),cache=new JSONObject(get("planetary.cache"));String place=location.optString("latitude")+","+location.optString("longitude");if(!place.equals(cache.optString("place")))throw new Exception();JSONObject current=cache.getJSONObject("data").getJSONObject("current");double temperature=current.optDouble("temperature_2m",Double.NaN);String reading=Double.isNaN(temperature)?"Unavailable":String.format(Locale.US,"%.0f °F",temperature);p.addView(paperText(reading,54,INK));p.addView(paperText(location.optString("name")+" / "+location.optString("admin1"),17,INK));long fetched=cache.optLong("fetched");long age=System.currentTimeMillis()-fetched;TextView stamp=paperText((age<0||age>=900000?"STALE CACHE":"Cached forecast")+" / "+new Date(fetched),14,MUTE);stamp.setMaxLines(3);p.addView(stamp);}catch(Exception e){TextView empty=paperText(get("planetary.location").isEmpty()?"Choose your location":"No cached forecast",27,INK);empty.setTypeface(Typeface.SERIF);p.addView(empty);p.addView(paperText("Tap to open local weather. No sample temperature is shown.",16,MUTE));}p.addView(paperText("Open forecast  >",16,palette().accent));p.setMinimumHeight(dp(154));p.setFocusable(true);p.setOnClickListener(v->planetaryData());return p;}
 LinearLayout todayPanel(){LinearLayout p=paperPanel("Today");p.setBackground(shape(INK,0,18));((TextView)p.getChildAt(0)).setTextColor(0xffc7c0b2);String date=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());String entry=get("event."+date);TextView title=paperText(entry.isEmpty()?"Make room for today.":entry,32,PAPER);title.setTypeface(Typeface.SERIF);title.setMaxLines(4);title.setEllipsize(android.text.TextUtils.TruncateAt.END);p.addView(title);p.addView(paperText(entry.isEmpty()?"Add your local calendar entry  >":"Open calendar  >",16,0xffd6cfc0));p.setMinimumHeight(dp(154));p.setFocusable(true);p.setOnClickListener(v->calendar());return p;}
 LinearLayout agendaPanel(){LinearLayout p=paperPanel("School agenda");try{JSONArray tasks=db().rows("SELECT t.title,t.due,n.name AS course FROM tasks t JOIN notebooks n ON n.id=t.notebook WHERE t.done=0 ORDER BY CASE WHEN t.due='' THEN 1 ELSE 0 END,t.due,t.important DESC LIMIT 3");if(tasks.length()==0)p.addView(paperText("No open assignments",24,INK));for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);String due=t.optString("due");TextView line=paperText(t.optString("title"),20,INK);line.setMaxLines(2);p.addView(line);p.addView(paperText(t.optString("course")+" / "+(due.isEmpty()?"No due date":due)+(due.isEmpty()?"":due.compareTo(todaySchool())<0?" / Overdue":due.equals(todaySchool())?" / Today":""),14,MUTE));}}catch(Exception e){p.addView(paperText("School agenda unavailable",20,INK));}p.addView(paperText("Open assignments  >",16,palette().accent));p.setMinimumHeight(dp(140));p.setFocusable(true);p.setOnClickListener(v->agenda(0,""));return p;}
 LinearLayout photoPanel(){LinearLayout p=paperPanel("Your photos");ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(PAPER2);p.addView(image,new LinearLayout.LayoutParams(-1,dp(220)));boolean remote=false;if(!token.isEmpty())for(JSONObject item:mediaItems)if(item.optString("type").equals("IMAGE")){thumb(image,server,token,item.optString("id"));remote=true;break;}if(!remote){File[] files=new File(getFilesDir(),"uploads").listFiles((d,n)->n.endsWith(".image"));if(files!=null&&files.length>0){Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));File selected=files[0];int stamp=revision;work(()->{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(selected.getPath(),options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>600||options.outHeight/options.inSampleSize>400)options.inSampleSize*=2;options.inJustDecodeBounds=false;Bitmap preview=BitmapFactory.decodeFile(selected.getPath(),options);ui.post(()->{if(stamp==revision)image.setImageBitmap(preview);else if(preview!=null)preview.recycle();});});}else{image.setVisibility(View.GONE);TextView empty=paperText("A place for your memories.",30,INK);empty.setTypeface(Typeface.SERIF);p.addView(empty);}}p.addView(paperText("Open albums and galleries  >",18,INK));p.addView(paperText("Uses an already loaded Immich selection or your latest uploaded photo.",14,MUTE));p.setMinimumHeight(dp(190));p.setFocusable(true);p.setOnClickListener(v->framePhotos());return p;}
 @Override void frameExplore(){super.frameExplore();button("Weather TV / WeatherStar with music",()->weatherTvIntro());}
 @Override void settings(){super.settings();button("Weather TV / external webpage",()->weatherTvIntro());}
 void weatherTvIntro(){page("Weather TV");text("WeatherStar 4000+ / third-party retro weather webpage. This is not an official Weatherscan broadcast.");text("Choose your location and use music/playback controls inside the webpage. Audio may require a tap inside the page. Site location/settings are separate from the native weather panel. The site and its data/music providers receive browsing requests; no Immich credentials or school data are injected.");button("Open WeatherStar fullscreen",()->openWeatherTv());button("Open in a compatible browser",()->externalWeatherTv());text("Internet required. The current website may not run in this frame's old WebView. If it stays blank or music does not work, use the browser option. No browser engine update, proxy, media download or local server is installed. Embedded playback stops when you leave or background this app.");}
 void externalWeatherTv(){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(WEATHER_TV)));}catch(Exception e){toast("No browser is available for this site");}}
 void openWeatherTv(){page("Weather TV");LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(INK);LinearLayout controls=new LinearLayout(this);controls.setBackgroundColor(PAPER);root.addView(controls,new LinearLayout.LayoutParams(-1,dp(58)));iconControl(controls,"Done",()->weatherTvIntro());iconControl(controls,"Reload",()->openWeatherTv());iconControl(controls,"Browser",()->externalWeatherTv());tvStatus=paperText("Loading WeatherStar / use the site's own music controls",14,PAPER);tvStatus.setPadding(dp(12),dp(4),dp(12),dp(4));root.addView(tvStatus);tvStage=new FrameLayout(this);root.addView(tvStage,new LinearLayout.LayoutParams(-1,0,1));web=new WebView(this);WebSettings config=web.getSettings();config.setJavaScriptEnabled(true);config.setDomStorageEnabled(true);config.setAllowFileAccess(false);config.setAllowContentAccess(false);config.setGeolocationEnabled(false);config.setMediaPlaybackRequiresUserGesture(true);if(Build.VERSION.SDK_INT>=21)config.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,String url){Uri u=Uri.parse(url);if("https".equalsIgnoreCase(u.getScheme())&&"weatherstar.netbymatt.com".equalsIgnoreCase(u.getHost()))return false;if(tvStatus!=null)tvStatus.setText("External navigation blocked here / use Browser to open links");return true;}public void onPageFinished(WebView view,String url){if(tvActive&&tvStatus!=null)tvStatus.setText("WeatherStar webpage / tap inside its music controls to enable sound");}public void onReceivedError(WebView view,int code,String description,String failing){if(tvActive&&tvStatus!=null)tvStatus.setText("Webpage error: "+description+" / try Browser");}public void onReceivedSslError(WebView view,android.webkit.SslErrorHandler handler,android.net.http.SslError error){handler.cancel();if(tvStatus!=null)tvStatus.setText("Secure connection failed / certificate bypass is disabled");}});tvStage.addView(web,new FrameLayout.LayoutParams(-1,-1));tvActive=true;setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);web.loadUrl(WEATHER_TV);}
 void stopTv(){if(!tvActive)return;tvActive=false;if(web!=null){web.stopLoading();web.loadUrl("about:blank");web.onPause();if(tvStage!=null)tvStage.removeView(web);web.destroy();web=null;}if(tvStatus!=null)tvStatus.setText("Weather TV stopped / tap Reload to reopen");getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 @Override protected void onPause(){stopTv();super.onPause();}
 @Override protected void onDestroy(){stopTv();super.onDestroy();}
}
